  ui_story_31380601_66_dialog_content = "PlayerName, você veio.",
  ui_story_31380601_67_dialog_content = "Ah... S-Siobhan?",
  ui_story_31380601_68_dialog_content = "Qual é o problema? Você não acha que estou fabulosa?",
  ui_story_31380601_69_dialog_content = "Você está tão linda que por um momento senti minha alma me deixar.",
  ui_story_31380601_70_dialog_content = "Sério? Obrigado!",
  ui_story_31380601_71_dialog_content = "Enquanto você achar que estou bem, sei que não tenho nada com que me preocupar.",
  ui_story_31380601_72_dialog_content = "Mas isso não significa que eu possa ficar complacente.",
  ui_story_31380601_73_dialog_content = "Pedi que viesse porque esperava que pudesse me dar sua análise honesta de um ponto de vista racional, neutro e objetivo.",
  ui_story_31380601_74_dialog_content = "Análise? É apenas um concurso de canto, pelo amor de Deus!",
  ui_story_31380601_75_dialog_content = "Como um acadêmico sério, preciso canalizar o espírito de pesquisa mesmo quando participo de um concurso de canto.",
  ui_story_31380601_76_dialog_content = "Eu até escrevi uma tese para esta competição.",
  ui_story_31380601_77_dialog_content = "É uma análise de vários fatores que afetam o resultado da competição - desde o palco até o sistema de competição, participantes e outros aspectos.",
  ui_story_31380601_78_dialog_content = "Vamos começar com o palco—",
  ui_story_31380601_79_dialog_content = "Este é um palco ao ar livre, então o desempenho será muito afetado pelo clima.",
  ui_story_31380601_80_dialog_content = "Se estiver ventando ou chovendo, isso prejudicaria o desempenho.",
  ui_story_31380601_81_dialog_content = "Portanto, durante o desempenho, devemos considerar o impacto potencial de várias condições climáticas.",
  ui_story_31380601_82_dialog_content = "Em seguida, vamos falar sobre o sistema de competição—",
  ui_story_31380601_83_dialog_content = "A primeira coisa a considerar é a audição em si, que pode ser considerada a fase mais difícil.",
  ui_story_31380601_84_dialog_content = "Se um único erro for cometido durante esta fase, os participantes serão eliminados e não terão mais chances de continuar participando.",
  ui_story_31380601_85_dialog_content = "Além disso, muitos dos participantes já acumularam certo grau de popularidade e uma considerável base de fãs antes do início da competição.",
  ui_story_31380601_86_dialog_content = "Eles terão uma vantagem maior na competição.",
  ui_story_31380601_87_dialog_content = "Então, o mais importante aqui é analisar os participantes!",
  ui_story_31380601_88_dialog_content = "Esta tabela mostra uma \"análise de classificação de ídolos\" para meus oponentes e para mim.",
  ui_story_31380601_89_dialog_content = "Inclui canto, dança, aparência, figura, QE e QI, com uma pontuação máxima de 5 para cada categoria.",
  ui_story_31380601_90_dialog_content = "Caronte—",
  ui_story_31380601_91_dialog_content = "Cantar — 5, dançar — 5, olhar — 4, figurar — 4, EQ — 0, QI — 3.",
  ui_story_31380601_92_dialog_content = "Um candidato popular para ocupar o primeiro lugar desta competição.",
  ui_story_31380601_93_dialog_content = "O metal gótico agita o coração como uma onda furiosa.",
  ui_story_31380601_94_dialog_content = "Ele tem vantagem suficiente para assustar seus oponentes.",
  ui_story_31380601_95_dialog_content = "Sua fraqueza é que seu baixo EQ não o levará longe.",
  ui_story_31380601_96_dialog_content = "Liliam—",
  ui_story_31380601_97_dialog_content = "Cantando: 2, dançando: 2, aparência: 4, figura: 3, QE: 1, QI: 5.",
  ui_story_31380601_98_dialog_content = "Produto da nova geração, eles possuem uma certa novidade por irem contra a lógica convencional.",
  ui_story_31380601_99_dialog_content = "A glória e a dignidade de quatro pessoas (máquinas) colocando tudo em risco para despertar seu corpo principal...",
  ui_story_31380601_100_dialog_content = "A fraqueza deles é que eles são muito robóticos.",
  ui_story_31380601_101_dialog_content = "Embora algumas pessoas sejam loucas por esse tipo de concorrente, elas não têm o que é preciso para conquistar o público em geral.",
  ui_story_31380601_102_dialog_content = "Sua análise é tão detalhada... Eu nunca teria imaginado que você fosse novo nesse tipo de coisa.",
  ui_story_31380601_103_dialog_content = "Não se esqueça, sou um pesquisador profissional!",
  ui_story_31380601_104_dialog_content = "Mas onde você conseguiu todas essas informações sobre seus concorrentes?",
  ui_story_31380601_105_dialog_content = "Bem, convidei o pessoal do cartório para um drinque.",
  ui_story_31380601_106_dialog_content = "Eles acabaram me contando tudo. Até eu fiquei chocado com a quantidade de informações que eles me deram.",
