  ui_story_31380601_108_dialog_content = "Você deu a eles uma gotinha de sua bebida favorita para soltar os lábios?",
  ui_story_31380601_109_dialog_content = "Bem, eu não me intrometi em nenhum assunto pessoal. Registrei apenas informações relacionadas à competição.",
  ui_story_31380601_110_dialog_content = "Ainda bem que foi você quem descobriu tudo isso. Se outra pessoa colocar as mãos nessas informações, isso pode significar más notícias para os outros participantes.",
  ui_story_31380601_111_dialog_content = "Não importa - vamos continuar inspecionando os dados do concorrente.",
  ui_story_31380601_112_dialog_content = "Eu apresentei um monte de concorrentes para você agora, mas o mais formidável é o seguinte—",
  ui_story_31380601_113_dialog_content = "O último e mais forte guerreiro da Família Sakura!",
  ui_story_31380601_114_dialog_content = "Olá!",
  ui_story_31380601_115_dialog_content = "Sua classificação específica não pode ser calculada agora, mas você pode ter certeza de que suas estatísticas estão fora das paradas.",
  ui_story_31380601_116_dialog_content = "O vencedor da competição do ano passado, Hiiro, é um oponente incrivelmente forte.",
  ui_story_31380601_117_dialog_content = "Tão sublime quanto uma flor de cerejeira flutuante e tão feroz quanto um dragão rugindo.",
  ui_story_31380601_118_dialog_content = "Não tenho certeza se há um auroriano vivo que possa vencê-la.",
  ui_story_31380601_119_dialog_content = "Eu nunca percebi que Hiiro era tão impressionante!",
  ui_story_31380601_120_dialog_content = "Então o que você vai fazer? Você vai tentar derrotar Hiiro?",
  ui_story_31380601_121_dialog_content = "Bem, quanto a mim, Siobhan...",
  ui_story_31380601_122_dialog_content = "Cantando: 1, dançando: 1, aparência: 6, figura: 6, QE: 5, QI: 5.",
