  ui_story_31380601_125_dialog_content = "*Tosse* Embora eu não seja bom em cantar ou dançar, as outras quatro áreas devem compensar isso.",
  ui_story_31380601_126_dialog_content = "Você está fingindo que não pode me ouvir?",
  ui_story_31380601_127_dialog_content = "Não importa, essas duas pontuações são objetivas de qualquer maneira.",
  ui_story_31380601_128_dialog_content = "Rá!",
  ui_story_31380601_129_dialog_content = "Você está rindo?",
  ui_story_31380601_130_dialog_content = "De qualquer forma... se eu der tudo de mim, terei uma chance de ganhar tudo isso.",
  ui_story_31380601_131_dialog_content = "Mas você foi um pouco duro consigo mesmo nas categorias de canto e dança... Você só deu um ponto para cada?",
  ui_story_31380601_132_dialog_content = "Você acha que se preparou bem o suficiente para ficar entre os três primeiros?",
