  ui_story_31380601_134_dialog_content = "Por que você não me mostra parte do seu desempenho e me deixa dar uma pontuação?",
  ui_story_31380601_135_dialog_content = "Você quer que eu faça uma performance agora? É tão repentino... Para ser honesto, estou me sentindo um pouco tímido.",
  ui_story_31380601_136_dialog_content = "Mas se é isso que você quer...",
  ui_story_31380601_137_dialog_content = "Ok, vamos fazer isso.",
  ui_story_31380601_138_dialog_content = "(Hmm... eu sei que esta é apenas a abertura de sua apresentação, mas o estilo de Siobhan não é nada ruim.)",
  ui_story_31380601_139_dialog_content = "(Passos leves, postura bonita, rosto bonito - ela tem uma boa chance de cativar a maioria das pessoas na platéia.)",
  ui_story_31380601_140_dialog_content = "♪ Vou trabalhar quando acordo, não tenho tempo para comer ♪",
  ui_story_31380601_141_dialog_content = "♪ Muito trabalho para lidar, não tenho tempo para dormir ♪",
  ui_story_31380601_142_dialog_content = "Espere aí, que tipo de música é essa!?",
  ui_story_31380601_143_dialog_content = "Eu escolhi uma música de rap aleatória das paradas mais cedo.",
  ui_story_31380601_144_dialog_content = "Pensei que fosse algum tipo de heavy metal...",
  ui_story_31380601_145_dialog_content = "A julgar pela sua expressão, suponho que não seja tão bom quanto costumava ser.",
  ui_story_31380601_146_dialog_content = "Você já se apresentou no palco antes?",
  ui_story_31380601_147_dialog_content = "Quando eu era muito jovem e morava em Undercity 66, dancei em algumas apresentações em grupo.",
  ui_story_31380601_148_dialog_content = "Quando você era muito jovem!?",
  ui_story_31380601_149_dialog_content = "Eu tinha apenas quatro ou cinco anos, mas ainda liderava a trupe.",
  ui_story_31380601_150_dialog_content = "Eu acho que eu poderia ter marcado pelo menos quatro em canto e dança naquela época.",
  ui_story_31380601_151_dialog_content = "Mas, considerando o fato de que não pratico há anos, presumi que minhas habilidades teriam se deteriorado significativamente, então dei uma pontuação objetiva de um ponto.",
  ui_story_31380601_152_dialog_content = "Sua avaliação de si mesmo é realmente muito racional, neutra e objetiva.",
  ui_story_31380601_153_dialog_content = "Agora parece que vai ser difícil vencer cantando e dançando sozinho.",
  ui_story_31380601_154_dialog_content = "Então, você acha que devo adicionar alguns dos meus talentos pessoais ao meu número de música e dança?",
  ui_story_31380601_155_dialog_content = "Que tipo de talentos pessoais?",
  ui_story_31380601_156_dialog_content = "Demolição-",
