  ui_story_31380601_158_dialog_content = "Então eu vou emergir da fumaça, dando ao público uma pequena surpresa.",
  ui_story_31380601_159_dialog_content = "(Não sei se o palco aguentaria uma explosão... Se desabar, com certeza seria uma surpresa.)",
  ui_story_31380601_160_dialog_content = "Camuflagem Avançada—",
  ui_story_31380601_161_dialog_content = "Vou me esconder na decoração e continuar cantando: \"Siobhan é o melhor\", para fazer lavagem cerebral nos transeuntes.",
  ui_story_31380601_162_dialog_content = "(É tão fácil fazer lavagem cerebral nas pessoas?)",
  ui_story_31380601_163_dialog_content = "Dança da Aranha—",
  ui_story_31380601_164_dialog_content = "Farei minhas adoráveis aranhas tecerem teias pelo palco, e cada pequena aranha pulará junto com a música.",
  ui_story_31380601_165_dialog_content = "Eles também podem vagar para o público para interagir com as pessoas. Todo mundo adoraria isso, certo?",
  ui_story_31380601_166_dialog_content = "(E se um membro da platéia sofre de aracnofobia, ele desmaia na hora...)",
  ui_story_31380601_167_dialog_content = "E o último é o Precision Dusting.",
  ui_story_31380601_168_dialog_content = "Se tudo mais falhar, ainda tenho esse ás na manga!",
  ui_story_31380601_169_dialog_content = "Eu removo poeira de antiguidades há muitos anos e dominei a habilidade única de tirar o pó.",
  ui_story_31380601_170_dialog_content = "Se eu espanar toda a platéia, eles ficarão satisfeitos comigo, não ficarão?",
  ui_story_31380601_171_dialog_content = "(Quando você de repente começa a invadir o espaço pessoal de todos com seu espanador, quem ficaria satisfeito com isso!?)",
  ui_story_31380601_172_dialog_content = "Estou ficando toda confusa! Qual habilidade devo usar?",
