  ui_story_31380601_176_dialog_content = "(A cabeça de Siobhan está tão baixa... Ela parece realmente desesperada.)",
  ui_story_31380601_177_dialog_content = "Suas habilidades são ótimas, mas não são adequadas para uma performance como esta.",
